package com.dtm.platform.config;import org.springframework.context.annotation.*;import org.springframework.boot.autoconfigure.jackson.Jackson2ObjectMapperBuilderCustomizer;import com.fasterxml.jackson.databind.DeserializationFeature;
@Configuration public class JacksonConfig {@Bean Jackson2ObjectMapperBuilderCustomizer customizer(){return b->b.featuresToDisable(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES).postConfigurer(mapper->mapper.getFactory().setStreamReadConstraints(com.fasterxml.jackson.core.StreamReadConstraints.builder().maxNestingDepth(50).maxStringLength(100000).build()));}}
